export type Locale = "en" | "pt-BR" | "fr" | "es";

export const LOCALES: { code: Locale; label: string; flag: string; native: string }[] = [
  { code: "en", label: "English", flag: "🇺🇸", native: "English" },
  { code: "pt-BR", label: "Português (Brasil)", flag: "🇧🇷", native: "Português" },
  { code: "fr", label: "Français", flag: "🇫🇷", native: "Français" },
  { code: "es", label: "Español", flag: "🇪🇸", native: "Español" },
];

export function resolveBrowserLocale(lang: string | undefined): Locale {
  if (!lang) return "en";
  const lower = lang.toLowerCase();
  if (lower.startsWith("pt")) return "pt-BR";
  if (lower.startsWith("fr")) return "fr";
  if (lower.startsWith("es")) return "es";
  return "en";
}

const tzCountry: Record<string, Locale> = {
  "America/Sao_Paulo": "pt-BR", "America/Bahia": "pt-BR", "America/Manaus": "pt-BR",
  "America/Fortaleza": "pt-BR", "America/Recife": "pt-BR", "America/Belem": "pt-BR",
  "Europe/Paris": "fr", "Europe/Brussels": "fr", "Europe/Luxembourg": "fr",
  "Europe/Madrid": "es", "Atlantic/Canary": "es", "America/Mexico_City": "es",
  "America/Buenos_Aires": "es", "America/Argentina/Buenos_Aires": "es",
  "America/Bogota": "es", "America/Lima": "es", "America/Santiago": "es",
  "America/Montevideo": "es",
};

export function localeFromTimezone(): Locale | null {
  if (typeof Intl === "undefined") return null;
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return tzCountry[tz] ?? null;
  } catch {
    return null;
  }
}

